// Use adds a list of mutation hooks to the hooks stack.
// A call to `Use(f, g, h)` equals to `tabletransfer.Hooks(f(g(h())))`.
func (c *TableTransferClient) Use(hooks ...Hook) {
	c.hooks.TableTransfer = append(c.hooks.TableTransfer, hooks...)
}

// Intercept adds a list of query interceptors to the interceptors stack.
// A call to `Intercept(f, g, h)` equals to `tabletransfer.Intercept(f(g(h())))`.
func (c *TableTransferClient) Intercept(interceptors ...Interceptor) {
	c.inters.TableTransfer = append(c.inters.TableTransfer, interceptors...)
}

// Create returns a builder for creating a TableTransfer entity.
func (c *TableTransferClient) Create() *TableTransferCreate {
	mutation := newTableTransferMutation(c.config, OpCreate)
	return &TableTransferCreate{config: c.config, hooks: c.Hooks(), mutation: mutation}
}

// CreateBulk returns a builder for creating a bulk of TableTransfer entities.
func (c *TableTransferClient) CreateBulk(builders ...*TableTransferCreate) *TableTransferCreateBulk {
	return &TableTransferCreateBulk{config: c.config, builders: builders}
}

// MapCreateBulk creates a bulk creation builder from the given slice. For each item in the slice, the function creates
// a builder and applies setFunc on it.
func (c *TableTransferClient) MapCreateBulk(slice any, setFunc func(*TableTransferCreate, int)) *TableTransferCreateBulk {
	rv := reflect.ValueOf(slice)
	if rv.Kind() != reflect.Slice {
		return &TableTransferCreateBulk{err: fmt.Errorf("calling to TableTransferClient.MapCreateBulk with wrong type %T, need slice", slice)}
	}
	builders := make([]*TableTransferCreate, rv.Len())
	for i := 0; i < rv.Len(); i++ {
		builders[i] = c.Create()
		setFunc(builders[i], i)
	}
	return &TableTransferCreateBulk{config: c.config, builders: builders}
}

